type Panel = 'slides' | 'properties' | 'ask' | 'palette' | 'graph' | 'knowledge' | 'tasks' | 'calendar' | 'history' | 'trash' | 'settings' | 'inspect' | 'vault' | 'canvas' | 'canvasPicker' | 'new' | 'connectors' | 'usage' | 'trust' | 'review' | 'account' | null;
const api = createGrimoireApi({onSessionExpired:()=>dispatchEvent(new Event('grimoire-session-expired'))});
const stem = (p: string) => p.replace(/\.md$/, '').split('/').pop() ?? p;
const display = (n: NoteListItem) => n.title || stem(n.path);
const lines = (body: string) => body.split('\n');
type PluginCommand = { icon?: string; name: string; run: () => void | Promise<void> };
type PluginSnippet = { name: string; detail?: string; insert: string | (() => string) };
const pluginContrib = { commands: [] as PluginCommand[], snippets: [] as PluginSnippet[], fences: new Map<string, (el: HTMLElement, source: string) => void | Promise<void>>(), transforms: [] as ((root: HTMLElement) => void | Promise<void>)[] };
const pluginScript = (url: string) => new Promise<void>((resolve, reject) => { const script = document.createElement('script'); script.src = url; script.onload = () => resolve(); script.onerror = () => reject(new Error(`plugin asset failed: ${url}`)); document.head.appendChild(script); });
const pluginStyles = (url: string) => { const link = document.createElement('link'); link.rel = 'stylesheet'; link.href = url; document.head.appendChild(link); };
const pluginsChanged = () => dispatchEvent(new Event('grimoire-plugins'));

function LinkButton({ target, children, open }: { target: string; children: React.ReactNode; open: (path: string) => void }) {
  return <a className="wikilink" href={'#' + encodeURIComponent(target)} onClick={e => { e.preventDefault(); void open(target); }}>{children}</a>;
}
function Markdown(props:React.ComponentProps<typeof RichMarkdown>){return <PreviewRoot><RichMarkdown {...props} pluginFence={(lang,source)=>pluginContrib.fences.has(lang)?<PluginFence lang={lang} source={source}/>:null}/></PreviewRoot>;}
function PluginFence({ lang, source }: { lang: string; source: string }) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { const render = pluginContrib.fences.get(lang); if (!ref.current || !render) return; ref.current.replaceChildren(); void Promise.resolve(render(ref.current, source)).catch(e => { if (ref.current) ref.current.textContent = `plugin render failed: ${e instanceof Error ? e.message : String(e)}`; }); }, [lang, source]); return pluginContrib.fences.has(lang) ? <div className={'fence-plugin fence-' + lang} ref={ref} /> : <pre><code data-lang={lang}>{source}</code></pre>; }
function PreviewRoot({ children }: { children: React.ReactNode }) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { if (ref.current) for (const transform of pluginContrib.transforms) void Promise.resolve(transform(ref.current)).catch(() => undefined); }); return <div className="md" ref={ref}>{children}</div>; }
