  const [sidebarCollapsed,setSidebarCollapsed]=useState(localStorage.getItem('grimoire-sidebar-collapsed')==='1'),[sideWidth,setSideWidth]=useState(Number(localStorage.getItem('grimoire-side-width'))||290),[mainWidth,setMainWidth]=useState<number>(),[zen,setZen]=useState(false);
