  const [palette, setPalette] = useState('');
  const [ask, setAsk] = useState(''); const [askResult, setAskResult] = useState<JsonValue>(); const [graph, setGraph] = useState<Graph>();
  const [tasks, setTasks] = useState<Task[]>([]); const [modalData, setModalData] = useState<JsonValue>(); const [canvas, setCanvas] = useState<Canvas>(); const [canvasRows, setCanvasRows] = useState<{ path: string; name?: string }[]>([]); const [canvasCardAt, setCanvasCardAt] = useState<{ x: number; y: number }>();
  const [knowledgeGraph, setKnowledgeGraph] = useState<KnowledgeGraph>(); const [knowledgeQuery, setKnowledgeQuery] = useState<KnowledgeQueryResult>();
  const [historyPreview,setHistoryPreview]=useState(''); const [historyRows, setHistoryRows] = useState<{ id: string; ts: number; size: number }[]>([]); const [trashRows, setTrashRows] = useState<{ id: string; title?: string; original?: string }[]>([]);
  const [templates, setTemplates] = useState<{ name: string; path?: string }[]>([]); const [outline, setOutline] = useState(false); const [contextPath, setContextPath] = useState<string>();
  const [tags, setTags] = useState<string[]>([]); const [completion, setCompletion] = useState('');
