  const dailyDate = () => /(?:^|\/)(\d{4}-\d{2}-\d{2})\.md$/.exec(activeRef.current?.path || '')?.[1] || todayDate();
  const openHistory = async () => { if (!active || !await save()) return; setPanel('history'); setHistoryPreview(''); try{setHistoryRows(await api.request<{id:string;ts:number;size:number}[]>(`/notes/${noteURLPath(active.path)}/history`));}catch(e){setError(String(e));} };
