  const upload = async (file?: File) => { const path=activeRef.current?.path;if(!file||!path)return;try{const form=new FormData();form.append('file',file);const out=await api.request<{path:string}>('/attach',{method:'POST',body:form});if(activeRef.current?.path!==path){setError('Attachment uploaded: '+out.path);return;}const insertion=`\n\n${/^image\//.test(file.type)?'!':''}[[${out.path}]]`;if(liveRef.current)liveRef.current.replaceSelection(insertion);else edit({body:activeRef.current.body+insertion});}catch(e){setError(String(e));}};
  const saveTemplate = () => { if (active) setForm({ kind: 'template', value: active.title }); };
