  const submitForm = async () => { if (!form) return; if (form.kind === 'template' && active) { await api.request('/templates', { method: 'POST', body: { name: form.value, body: active.body } }); setTemplates(await api.templates()); setPanel(null); } if (form.kind === 'apply' && form.path) { const n = await api.request<{ path: string }>('/templates/apply', { method: 'POST', body: { template: form.path, title: form.value } }); await refresh(); await open(n.path); setPanel(null); } if (form.kind === 'rename' && form.path) { const prior = await api.note(form.path); await api.request(`/notes/${noteURLPath(form.path)}`, { method: 'PUT', body: { body: prior.body, frontmatter: { ...prior.frontmatter, title: form.value } } }); const dir = form.path.includes('/') ? form.path.slice(0, form.path.lastIndexOf('/') + 1) : ''; const n = await api.request<{ path: string }>(`/notes/${noteURLPath(form.path)}/rename`, { method: 'POST', body: { to: dir + form.value.toLowerCase().replace(/[^a-z0-9]+/g, '-') + '.md' } }); await refresh(); await open(n.path); } if (form.kind === 'canvas') { const made = await api.request<{ path: string }>('/canvas', { method: 'POST', body: { name: form.value } }); setCanvas(await api.canvas(made.path)); setPanel('canvas'); } if (form.kind === 'card' && canvas && canvasCardAt && form.value.trim()) { const next = { ...canvas, nodes: [...canvas.nodes, { id: `n${Date.now().toString(36)}`, type: 'text', text: form.value.trim(), x: canvasCardAt.x, y: canvasCardAt.y, width: 200, height: 80 }] }; await api.request(`/canvas/${noteURLPath(next.path)}`, { method: 'PUT', body: { nodes: next.nodes, edges: next.edges } as unknown as JsonValue }); setCanvas(next); setCanvasCardAt(undefined); } if (form.kind === 'restore' && form.id) await restoreVersion(form.id); setForm(undefined); };
