    if((q.includes('extract selection')||q.includes('merge this note'))&&active&&!active.locked){const selection=liveRef.current?.getSelection()||{from:contentRef.current?.selectionStart||0,to:contentRef.current?.selectionEnd||0};const kind=q.includes('extract')?'extract':'merge';if(kind==='extract'&&!active.body.slice(selection.from,selection.to).trim()){setError('Select some text to extract first.');setPanel(null);return;}setComposition({kind,note:structuredClone(active),...selection});setPanel(null);return;}
