  const renderRows = (items: NoteListItem[]) => { const folders = new Map<string, NoteListItem[]>(); for (const n of items) { const f = n.path.includes('/') ? n.path.split('/')[0]! : ''; folders.set(f, [...(folders.get(f) || []), n]); } return [...folders].sort(([a], [b]) => a.localeCompare(b)).map(([folder, ns]) => folder ? <details className="folder" key={folder} open><summary>{folder}/</summary>{ns.map(n => <NoteRow n={n} key={n.path} active={active?.path === n.path} keyboard={visible[kbdIndex]?.path===n.path} open={open} split={path=>void api.note(path).then(setSplit).catch(e=>setError(String(e)))} context={setContextPath} />)}</details> : <div key="root">{ns.map(n => <NoteRow n={n} key={n.path} active={active?.path === n.path} keyboard={visible[kbdIndex]?.path===n.path} open={open} split={path=>void api.note(path).then(setSplit).catch(e=>setError(String(e)))} context={setContextPath} />)}</div>); };
