function SettingsPanel({ close }: { close: () => void }) { const [values, setValues] = useState<Record<string, JsonValue>>({}); const [backend, setBackend] = useState(''); const [error, setError] = useState<unknown>(); const load = useCallback(() => api.settings().then(r => { setValues(r.settings); setBackend(r.answer_backend || ''); }).catch(setError), []); useEffect(() => { void load(); }, [load]); const save = () => void api.request('/settings', { method: 'PUT', body: values }).then(() => close()).catch(setError); return <Modal id="settings-modal" close={close}><h2 id="inspect-title">Settings</h2><div id="settings-body"><p className="vault-note">Answer mode: <b>{backend}</b></p><Gate error={error} />{Object.entries(values).map(([k, v]) => <label className="setting" key={k}>{k}{typeof v === 'boolean' ? <input type="checkbox" checked={v} onChange={e => setValues({ ...values, [k]: e.target.checked })} /> : <input id={k === 'llm_model' ? 'set-model' : undefined} value={typeof v === 'string' || typeof v === 'number' ? String(v) : JSON.stringify(v)} onChange={e => setValues({ ...values, [k]: e.target.value })} />}</label>)}<button id="set-save" className="btn" onClick={save}>Save settings</button><PluginControls /></div></Modal>; }
